-- DQ-004: Histological Type Domain---- Purpose:-- Validate the observed values of the histological.type-- variable in the staging layer.---- Expected categories:-- - infiltrating ductal carcinoma-- - infiltrating lobular carcinoma---- Expected record counts:-- - infiltrating ductal carcinoma = 574-- - infiltrating lobular carcinoma = 131-- - total records = 705---- This validation does not modify the data.SELECT    "histological.type",    COUNT(*) AS quantityFROM staging.brca_sample_wideGROUP BY "histological.type"ORDER BY quantity DESC;